// THE FINAL REHEARSAL — scene entry point.
// Static arena lives in assets/scene/main.composite (generated by `npm run arena`).
import { engine } from '@dcl/sdk/ecs'
import { SESSION } from './config'
import { createWatcher } from './boss/watcher'
import { initImprint } from './combat/imprint'
import { createTracerPool } from './effects/tracers'
import { initEchoes } from './echoes/echoSystem'
import { createEchoViews } from './echoes/echoView'
import { state } from './game/state'
import { setupHud } from './ui/hud'
import { initSession } from './game/session'
import { initAttacks } from './boss/attacks'
import { initVfx } from './effects/vfx'
import { initProjectiles } from './effects/projectiles'
import { initAtmosphere } from './scene/atmosphere'
import { initPhases } from './game/phases'
import { initCorruption } from './boss/corruption'
import { initChamber } from './scene/chamber'

/** Single session clock. Runs first each frame; large hitches are clamped. */
function clockSystem(dt: number) {
  state.time += Math.min(dt, SESSION.maxFrameDt)
}

export function main() {
  engine.addSystem(clockSystem, 200000, "clock") // higher priority runs first (regular = 100000)
  initSession()
  initAtmosphere()
  initChamber()
  initVfx()
  createWatcher()
  createTracerPool()
  initProjectiles()
  initImprint()
  initEchoes()
  createEchoViews()
  initPhases()
  initCorruption()
  initAttacks()
  setupHud()
  console.log('[FinalRehearsal] M4 loaded (phases, corruption, Blind Spot, Final Observation)')
}
